head.script:
scwin.onpageload = function() {
    document.title = "AutoComplete";

    var arr = ["test1","t1","","test2","t2","","test3-f가나다라마바사가나다라마바사","t3","false","aaa1","a1","","aaa2","a2","","bbb1","b1","","bbb2","b2",""];
    autoItemSet.setData(arr);
};

	scwin.subfunc = function(searchStr, keyCode){
		console.log(searchStr);
		$p.executeSubmission( "submission1", searchStr);
	};   


	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#acb_samp_input', 'key-combo', {
			combo: 'ENTER'
		});
	}

	scwin.isWithinPercent = function(a, b, c) {
	  const percentage = c; // 백분율 설정
	  const lowerBound = b - (b * (percentage / 100)); // 하한 계산
	  const upperBound = b + (b * (percentage / 100)); // 상한 계산
debugger;
	  return a >= lowerBound && a <= upperBound;
	}	

	scwin.checkVal = function() {
		let check_val = WebSquare.wUnit.getJq('#acb_samp_div_input').width()
		return scwin.isWithinPercent(check_val, 142, 2);
	}	

	scwin.unitTest = function(){
		//init
		WebSquare.wUnit.start();

		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('acb_samp_arrow').click()");
		WebSquare.wUnit.addCommand("pause", "500");			

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('acb_samp_itemTable_option3').click()");
		WebSquare.wUnit.addCommand("pause", "500");			

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('acb_samp_input').click()");
		WebSquare.wUnit.addCommand("pause", "500");			

		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
